async function getTeamStandingsSnapshot(guildId, leagueId, teamRoleId) {
  const result = await pool.query(
    `SELECT wins, losses, points_for, points_against
     FROM league_standings
     WHERE guild_id = $1 AND league_id = $2 AND team_role_id = $3`,
    [guildId, leagueId, teamRoleId]
  );

  const row = result.rows[0] || { wins: 0, losses: 0, points_for: 0, points_against: 0 };
  const wins = Number(row.wins || 0);
  const losses = Number(row.losses || 0);
  const games = wins + losses;
  const winPct = games ? wins / games : 0.5;
  const pointDiff = Number(row.points_for || 0) - Number(row.points_against || 0);

  return { wins, losses, games, winPct, pointDiff };
}

async function getTeamRecentForm(guildId, leagueId, teamRoleId) {
  const result = await pool.query(
    `SELECT winner_team_role_id
     FROM league_games
     WHERE guild_id = $1
       AND league_id = $2
       AND status = 'final'
       AND (home_team_role_id = $3 OR away_team_role_id = $3)
     ORDER BY updated_at DESC
     LIMIT 5`,
    [guildId, leagueId, teamRoleId]
  );

  let streak = 0;
  for (const row of result.rows) {
    const won = row.winner_team_role_id === teamRoleId;
    if (streak === 0) {
      streak = won ? 1 : -1;
    } else if ((streak > 0 && won) || (streak < 0 && !won)) {
      streak += won ? 1 : -1;
    } else {
      break;
    }
  }

  const recentWins = result.rows.filter(row => row.winner_team_role_id === teamRoleId).length;
  return { recentWins, streak };
}

async function getHeadToHeadSnapshot(guildId, leagueId, homeRoleId, awayRoleId) {
  const result = await pool.query(
    `SELECT winner_team_role_id
     FROM league_games
     WHERE guild_id = $1
       AND league_id = $2
       AND status = 'final'
       AND (
         (home_team_role_id = $3 AND away_team_role_id = $4)
         OR
         (home_team_role_id = $4 AND away_team_role_id = $3)
       )
     ORDER BY updated_at DESC
     LIMIT 10`,
    [guildId, leagueId, homeRoleId, awayRoleId]
  );

  const homeWins = result.rows.filter(row => row.winner_team_role_id === homeRoleId).length;
  const awayWins = result.rows.filter(row => row.winner_team_role_id === awayRoleId).length;
  return { homeWins, awayWins, games: result.rows.length };
}

function probabilityToAmericanOdds(probability) {
  const p = Math.max(0.15, Math.min(0.85, Number(probability) || 0.5));
  if (p >= 0.5) return -Math.round((p / (1 - p)) * 100);
  return Math.round(((1 - p) / p) * 100);
}

async function generateAutoSportsbookOdds(guildId, leagueId, homeRoleId, awayRoleId) {
  const home = await getTeamStandingsSnapshot(guildId, leagueId, homeRoleId);
  const away = await getTeamStandingsSnapshot(guildId, leagueId, awayRoleId);
  const homeForm = await getTeamRecentForm(guildId, leagueId, homeRoleId);
  const awayForm = await getTeamRecentForm(guildId, leagueId, awayRoleId);
  const h2h = await getHeadToHeadSnapshot(guildId, leagueId, homeRoleId, awayRoleId);

  let homeScore = 50;
  homeScore += (home.winPct - away.winPct) * 35;
  homeScore += (home.pointDiff - away.pointDiff) * 0.03;
  homeScore += (homeForm.recentWins - awayForm.recentWins) * 2.5;
  homeScore += (homeForm.streak - awayForm.streak) * 1.5;
  homeScore += (h2h.homeWins - h2h.awayWins) * 2;
  homeScore += 3; // home-field/home-court advantage

  const homeProbability = Math.max(0.2, Math.min(0.8, homeScore / 100));
  const awayProbability = 1 - homeProbability;

  return {
    homeOdds: probabilityToAmericanOdds(homeProbability),
    awayOdds: probabilityToAmericanOdds(awayProbability),
    homeProbability,
    awayProbability,
  };
}

async function createAutoSportsbookForLeagueGame(interaction, leagueGame, league) {
  if (!interaction.guild || !leagueGame || !league?.league_id) return null;

  const existing = await pool.query(
    `SELECT * FROM sportsbook_games WHERE guild_id = $1 AND league_game_id = $2 LIMIT 1`,
    [interaction.guild.id, leagueGame.id]
  );
  if (existing.rows.length) return existing.rows[0];

  const odds = await generateAutoSportsbookOdds(
    interaction.guild.id,
    league.league_id,
    leagueGame.home_team_role_id,
    leagueGame.away_team_role_id
  );

  const sportsbookGameId = randomUUID();
  const label = leagueGame.home_team_name + ' vs ' + leagueGame.away_team_name;

  await pool.query(
    `INSERT INTO sportsbook_games
      (id, guild_id, league_id, league_game_id, game_label, home_label, away_label, home_odds, away_odds, source, auto_generated, created_by_user_id)
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, 'game_add', TRUE, $10)`,
    [
      sportsbookGameId,
      interaction.guild.id,
      league.league_id,
      leagueGame.id,
      label,
      leagueGame.home_team_name,
      leagueGame.away_team_name,
      odds.homeOdds,
      odds.awayOdds,
      interaction.user.id,
    ]
  );

  await updateSportsbookPanel(interaction.guild).catch(() => null);

  const sportsbookGame = {
    id: sportsbookGameId,
    guild_id: interaction.guild.id,
    league_id: league.league_id,
    league_game_id: leagueGame.id,
    game_label: label,
    home_label: leagueGame.home_team_name,
    away_label: leagueGame.away_team_name,
    home_odds: odds.homeOdds,
    away_odds: odds.awayOdds,
  };

  const feedEmbed = new EmbedBuilder()
    .setTitle('📈 Sportsbook Line Opened')
    .setColor(0x57F287)
    .addFields(
      { name: 'Game', value: label, inline: false },
      { name: leagueGame.home_team_name, value: 'ML ' + odds.homeOdds, inline: true },
      { name: leagueGame.away_team_name, value: 'ML ' + odds.awayOdds, inline: true },
      { name: 'Source', value: 'Auto-generated from /game add', inline: false }
    )
    .setFooter({ text: 'GG Sports • Auto Sportsbook' })
    .setTimestamp();

  await postSportsbookFeed(interaction.guild, feedEmbed);
  return sportsbookGame;
}


async function resetSportsbookForLeagueGame(guild, leagueGame, issuedByUserId, reason = 'Game reset') {
  if (!guild || !leagueGame) return { reset: false, refundedCount: 0, refundedAmount: 0 };

  const result = await pool.query(
    `SELECT * FROM sportsbook_games
     WHERE guild_id = $1 AND league_game_id = $2
     ORDER BY created_at DESC
     LIMIT 1`,
    [guild.id, leagueGame.id]
  );

  if (!result.rows.length) return { reset: false, refundedCount: 0, refundedAmount: 0 };

  const sportsbookGame = result.rows[0];
  const settings = await getCurrencySettings(guild.id);

  const bets = await pool.query(
    `SELECT * FROM sportsbook_bets
     WHERE guild_id = $1 AND sportsbook_game_id = $2 AND status IN ('open','won','lost')`,
    [guild.id, sportsbookGame.id]
  );

  let refundedCount = 0;
  let refundedAmount = 0;

  for (const bet of bets.rows) {
    if (bet.status === 'open') {
      await addCurrency(guild.id, bet.user_id, Number(bet.amount), 'sportsbook_reset_refund', reason, issuedByUserId);
      refundedAmount += Number(bet.amount);
    } else if (bet.status === 'won') {
      // Best-effort reversal: remove the payout that was previously paid.
      await removeCurrency(guild.id, bet.user_id, Number(bet.potential_payout), 'sportsbook_reset_reversal', reason, issuedByUserId).catch(() => null);
    }

    await pool.query(
      `UPDATE sportsbook_bets SET status = 'refunded', settled_at = NOW() WHERE id = $1`,
      [bet.id]
    );
    refundedCount += 1;
  }

  await pool.query(
    `UPDATE sportsbook_games
     SET status = 'open', winner_side = NULL, settled_at = NULL, settled_by_game_report = FALSE
     WHERE id = $1`,
    [sportsbookGame.id]
  );

  await pool.query(
    `UPDATE sportsbook_parlay_legs
     SET status = 'open'
     WHERE sportsbook_game_id = $1`,
    [sportsbookGame.id]
  ).catch(() => null);

  await pool.query(
    `UPDATE sportsbook_parlays
     SET status = 'open', settled_at = NULL
     WHERE id IN (
       SELECT parlay_id FROM sportsbook_parlay_legs WHERE sportsbook_game_id = $1
     )`,
    [sportsbookGame.id]
  ).catch(() => null);

  await updateSportsbookPanel(guild).catch(() => null);

  const embed = new EmbedBuilder()
    .setTitle('♻️ Sportsbook Reopened')
    .setColor(0xFEE75C)
    .addFields(
      { name: 'Game', value: sportsbookGame.game_label || 'Unknown game', inline: false },
      { name: 'Reason', value: reason || 'Game reset', inline: false },
      { name: 'Bets Reset/Refunded', value: String(refundedCount), inline: true },
      { name: 'Amount Refunded', value: settings.currency_icon + ' ' + refundedAmount, inline: true }
    )
    .setFooter({ text: 'GG Sports • Game Reset' })
    .setTimestamp();

  await postSportsbookFeed(guild, embed).catch(() => null);

  return { reset: true, refundedCount, refundedAmount };
}

async function autoSettleSportsbookForLeagueGame(interaction, leagueGame, winnerSide) {
  if (!interaction.guild || !leagueGame) return null;

  let result = await pool.query(
    `SELECT * FROM sportsbook_games
     WHERE guild_id = $1 AND league_game_id = $2 AND status = 'open'
     LIMIT 1`,
    [interaction.guild.id, leagueGame.id]
  );

  if (!result.rows.length) {
    result = await pool.query(
      `SELECT * FROM sportsbook_games
       WHERE guild_id = $1
         AND status = 'open'
         AND LOWER(home_label) = LOWER($2)
         AND LOWER(away_label) = LOWER($3)
       ORDER BY created_at DESC
       LIMIT 1`,
      [interaction.guild.id, leagueGame.home_team_name, leagueGame.away_team_name]
    );
  }

  if (!result.rows.length) return null;

  const sportsbookGame = result.rows[0];
  const fakeSettlePayload = {
    sportsbookGame,
    winner: winnerSide,
  };

  const settings = await getCurrencySettings(interaction.guild.id);
  const bets = await pool.query(
    `SELECT * FROM sportsbook_bets
     WHERE guild_id = $1 AND sportsbook_game_id = $2 AND status = 'open'`,
    [interaction.guild.id, sportsbookGame.id]
  );

  let winners = 0;
  let losers = 0;
  let totalPaid = 0;

  for (const bet of bets.rows) {
    if (bet.side === winnerSide) {
      await addCurrency(interaction.guild.id, bet.user_id, Number(bet.potential_payout), 'sportsbook_win', 'Auto-settled bet: ' + sportsbookGame.game_label, interaction.user.id);
      await pool.query(`UPDATE sportsbook_bets SET status = 'won', settled_at = NOW() WHERE id = $1`, [bet.id]);
      await addActivityPoints(interaction.guild.id, bet.user_id, 5, 2).catch(() => null);
      winners += 1;
      totalPaid += Number(bet.potential_payout);
    } else {
      await pool.query(`UPDATE sportsbook_bets SET status = 'lost', settled_at = NOW() WHERE id = $1`, [bet.id]);
      losers += 1;
    }
  }

  await pool.query(
    `UPDATE sportsbook_games
     SET status = 'settled', winner_side = $1, settled_at = NOW(), settled_by_game_report = TRUE
     WHERE id = $2`,
    [winnerSide, sportsbookGame.id]
  );

  const parlayResult = typeof settleParlaysForSportsbookGame === 'function'
    ? await settleParlaysForSportsbookGame(interaction.guild.id, sportsbookGame.id, winnerSide, interaction.user.id)
    : { settledCount: 0, parlayPaid: 0 };

  await updateSportsbookPanel(interaction.guild).catch(() => null);

  const winnerLabel = winnerSide === 'home' ? sportsbookGame.home_label : sportsbookGame.away_label;
  const feedEmbed = new EmbedBuilder()
    .setTitle('✅ Sportsbook Auto-Settled')
    .setColor(0x57F287)
    .addFields(
      { name: 'Game', value: sportsbookGame.game_label, inline: false },
      { name: 'Winner', value: winnerLabel, inline: true },
      { name: 'Winning Bets', value: String(winners), inline: true },
      { name: 'Losing Bets', value: String(losers), inline: true },
      { name: 'Total Paid', value: settings.currency_icon + ' ' + totalPaid, inline: true },
      { name: 'Parlays Settled', value: String(parlayResult.settledCount || 0), inline: true }
    )
    .setFooter({ text: 'GG Sports • Auto Sportsbook' })
    .setTimestamp();

  await postSportsbookFeed(interaction.guild, feedEmbed);

  return { sportsbookGame, winners, losers, totalPaid, parlayResult };
}



async function userIsInLeagueGame(guild, userId, sportsbookGame) {
  if (!guild || !userId || !sportsbookGame) return false;

  const member = await guild.members.fetch(userId).catch(() => null);
  if (!member) return false;

  if (sportsbookGame.league_game_id) {
    const gameResult = await pool.query(
      `SELECT * FROM league_games WHERE id = $1 LIMIT 1`,
      [sportsbookGame.league_game_id]
    );
    const game = gameResult.rows[0];
    if (game && (member.roles.cache.has(game.home_team_role_id) || member.roles.cache.has(game.away_team_role_id))) {
      return true;
    }
  }

  const homeLabel = String(sportsbookGame.home_label || '').toLowerCase();
  const awayLabel = String(sportsbookGame.away_label || '').toLowerCase();

  return member.roles.cache.some(role =>
    role.name.toLowerCase() === homeLabel ||
    role.name.toLowerCase() === awayLabel
  );
}


async function refundSportsbookGameBets(guild, sportsbookGame, issuedByUserId, reason = 'Sportsbook refund') {
  if (!guild || !sportsbookGame) return { refundedCount: 0, refundedAmount: 0 };

  const openBets = await pool.query(
    `SELECT * FROM sportsbook_bets
     WHERE guild_id = $1 AND sportsbook_game_id = $2 AND status = 'open'`,
    [guild.id, sportsbookGame.id]
  );

  let refundedCount = 0;
  let refundedAmount = 0;

  for (const bet of openBets.rows) {
    await addCurrency(guild.id, bet.user_id, Number(bet.amount), 'sportsbook_refund', reason, issuedByUserId);
    await pool.query(`UPDATE sportsbook_bets SET status = 'refunded', settled_at = NOW() WHERE id = $1`, [bet.id]);
    refundedCount += 1;
    refundedAmount += Number(bet.amount);
  }

  await pool.query(`UPDATE sportsbook_games SET status = 'refunded', settled_at = NOW() WHERE id = $1`, [sportsbookGame.id]);
  await updateSportsbookPanel(guild).catch(() => null);

  const settings = await getCurrencySettings(guild.id);
  const embed = new EmbedBuilder()
    .setTitle('↩️ Sportsbook Bets Refunded')
    .setColor(0xFEE75C)
    .addFields(
      { name: 'Game', value: sportsbookGame.game_label || 'Unknown game', inline: false },
      { name: 'Bets Refunded', value: String(refundedCount), inline: true },
      { name: 'Amount Returned', value: settings.currency_icon + ' ' + refundedAmount, inline: true },
      { name: 'Reason', value: reason || 'Sportsbook refund', inline: false }
    )
    .setFooter({ text: 'GG Sports • Sportsbook Refund' })
    .setTimestamp();

  await postSportsbookFeed(guild, embed);
  return { refundedCount, refundedAmount };
}

async function findSportsbookGame(guildId, input) {
  const result = await pool.query(
    `SELECT * FROM sportsbook_games
     WHERE guild_id = $1 AND (id::text LIKE $2 OR LOWER(game_label) = LOWER($3))
     ORDER BY created_at DESC
     LIMIT 1`,
    [guildId, input + '%', input]
  );
  return result.rows[0] || null;
}

async function applyApprovedGameIssue(ticket, reviewerUserId) {
  if (!ticket.game_id || !ticket.league_id || !ticket.request_action) {
    return 'Decision saved. No game update was applied because this ticket is missing game metadata.';
  }

  const gameResult = await pool.query(
    `SELECT * FROM league_games
     WHERE guild_id = $1 AND league_id = $2 AND id::text LIKE $3
     ORDER BY created_at DESC
     LIMIT 1`,
    [ticket.guild_id, ticket.league_id, ticket.game_id + '%']
  );

  if (!gameResult.rows.length) {
    return 'Decision saved, but no matching game was found for Game ID **' + ticket.game_id + '**.';
  }

  const game = gameResult.rows[0];
  const league = await getLeagueById(ticket.league_id);

  if (ticket.request_action === 'reset') {
    await pool.query(
      `UPDATE league_games
       SET status = 'scheduled', home_score = NULL, away_score = NULL, winner_team_role_id = NULL, reported_by_user_id = $1, updated_at = NOW()
       WHERE id = $2`,
      [reviewerUserId, game.id]
    );
    return 'Game **' + shortGameId(game.id) + '** has been reset/reopened.';
  }

  const requestedTeamRoleId = ticket.requested_team_role_id;
  if (!requestedTeamRoleId) {
    return 'Decision saved. No force win was applied because no requesting team role was saved.';
  }

  if (![game.home_team_role_id, game.away_team_role_id].includes(requestedTeamRoleId)) {
    return 'Decision saved. No force win was applied because the requesting team is not part of this game.';
  }

  const homeWins = requestedTeamRoleId === game.home_team_role_id;
  const homeScore = homeWins ? 1 : 0;
  const awayScore = homeWins ? 0 : 1;
  const winnerRoleId = requestedTeamRoleId;
  const loserRoleId = homeWins ? game.away_team_role_id : game.home_team_role_id;
  const winnerName = homeWins ? game.home_team_name : game.away_team_name;
  const loserName = homeWins ? game.away_team_name : game.home_team_name;

  if (game.status === 'final') {
    return 'Decision saved. Game **' + shortGameId(game.id) + '** was already final, so standings were not changed automatically.';
  }

  await pool.query(
    `UPDATE league_games
     SET status = 'final', home_score = $1, away_score = $2, winner_team_role_id = $3, reported_by_user_id = $4, updated_at = NOW()
     WHERE id = $5`,
    [homeScore, awayScore, winnerRoleId, reviewerUserId, game.id]
  );

  await pool.query(
    `INSERT INTO league_standings (guild_id, league_id, team_role_id, team_name, wins, losses, standings_points)
     VALUES ($1, $2, $3, $4, 1, 0, 3)
     ON CONFLICT (guild_id, league_id, team_role_id)
     DO UPDATE SET wins = league_standings.wins + 1, standings_points = league_standings.standings_points + 3, updated_at = NOW()`,
    [ticket.guild_id, ticket.league_id, winnerRoleId, winnerName]
  );

  await pool.query(
    `INSERT INTO league_standings (guild_id, league_id, team_role_id, team_name, wins, losses, standings_points)
     VALUES ($1, $2, $3, $4, 0, 1, 1)
     ON CONFLICT (guild_id, league_id, team_role_id)
     DO UPDATE SET losses = league_standings.losses + 1, standings_points = league_standings.standings_points + 1, updated_at = NOW()`,
    [ticket.guild_id, ticket.league_id, loserRoleId, loserName]
  );

  const guild = await client.guilds.fetch(ticket.guild_id).catch(() => null);
  if (guild && league) await updateStandingsPanel(guild, league);

  return 'Approved ruling applied: **' + winnerName + '** receives a force win over **' + loserName + '** for Game **' + shortGameId(game.id) + '**.';
}

async function openGameIssueTicket(interaction, ticketType) {
  if (!interaction.guild) return;

  const leagueName = interaction.options.getString('league');
  const gameId = interaction.options.getString('game_id');
  const opponent = interaction.options.getUser('opponent');
  const team = interaction.options.getRole('team');
  const details = interaction.options.getString('details');
  const activeLeague = await getLeagueByName(interaction.guild.id, leagueName);

  if (!activeLeague) {
    await interaction.reply({ content: 'Could not find league **' + leagueName + '**.', ephemeral: true });
    return;
  }

  const subject = ticketType + ' review' + (gameId ? ' • Game ' + gameId : '');
  const NL = String.fromCharCode(10);
  let description = '**League:** ' + activeLeague.league_name;
  if (gameId) description += NL + '**Game ID:** ' + gameId;
  if (team) description += NL + '**Requesting Team:** ' + team.toString();
  if (opponent) description += NL + '**Opponent:** ' + opponent.toString();
  description += NL + '**Request Type:** ' + ticketType;
  description += NL + '**Details:** ' + (details || 'No details provided yet.');
  description += NL + NL + 'Please upload proof/screenshots in this ticket thread. Attachments will be saved automatically as evidence.';

  const originalGetString = interaction.options.getString.bind(interaction.options);
  interaction.options.getString = function(name) {
    if (name === 'subject') return subject;
    if (name === 'description') return description;
    if (name === 'league') return activeLeague.league_name;
    return originalGetString(name);
  };

  const requestedTeamRoleId = team?.id || null;
  const opponentUserId = opponent?.id || null;

  interaction.ggSportsReviewButtons = true;
  interaction.ggSportsGameIssueMeta = {
    gameId,
    requestAction: ticketType,
    requestedTeamRoleId,
    opponentUserId,
  };

  await openSupportTicket(interaction, 'gamerequest');
  delete interaction.ggSportsReviewButtons;
  delete interaction.ggSportsGameIssueMeta;
}

async function openSupportTicket(interaction, ticketType) {
  if (!interaction.guild) return;

  const shouldAddReviewButtons = interaction.ggSportsReviewButtons === true;
  const gameIssueMeta = interaction.ggSportsGameIssueMeta || null;

  const subject = interaction.options.getString('subject');
  const description = interaction.options.getString('description');
  const leagueName = interaction.options.getString('league');
  const activeLeague = leagueName ? await getLeagueByName(interaction.guild.id, leagueName) : await resolveLeague(interaction);

  if (leagueName && !activeLeague) {
    await interaction.reply({ content: 'Could not find league **' + leagueName + '**.', ephemeral: true });
    return;
  }

  const baseChannel = interaction.channel;
  if (!baseChannel || !baseChannel.isTextBased()) {
    await interaction.reply({ content: 'Tickets can only be opened from a text channel.', ephemeral: true });
    return;
  }

  const botMember = await interaction.guild.members.fetchMe();
  const permissions = baseChannel.permissionsFor(botMember);
  if (!permissions?.has(PermissionFlagsBits.ViewChannel) || !permissions?.has(PermissionFlagsBits.SendMessages) || !permissions?.has(PermissionFlagsBits.CreatePublicThreads)) {
    await interaction.reply({ content: 'I need View Channel, Send Messages, and Create Public Threads permissions here to open tickets.', ephemeral: true });
    return;
  }

  const safeSubject = subject.replace(/[^a-zA-Z0-9 -]/g, '').trim().slice(0, 40) || ticketType;
  const threadName = (ticketType + '-' + interaction.user.username + '-' + safeSubject).slice(0, 90);
  const staffRoleId = activeLeague?.staff_role_id || null;

  const starterPayload = {
    content: '<@' + interaction.user.id + '> opened a **' + ticketType + '** ticket.' + (staffRoleId ? ' <@&' + staffRoleId + '>' : ''),
    embeds: [buildTicketEmbed({ type: ticketType, subject, description, creator: interaction.user })],
    allowedMentions: {
      users: [interaction.user.id],
      roles: staffRoleId ? [staffRoleId] : [],
    },
  };

  const starter = await baseChannel.send(starterPayload);

  const thread = await starter.startThread({
    name: threadName,
    autoArchiveDuration: 1440,
    reason: 'GG Sports ' + ticketType + ' ticket',
  }).catch(() => null);

  if (!thread) {
    await interaction.reply({ content: 'I could not create the ticket thread. Make sure I have Create Public Threads permission.', ephemeral: true });
    return;
  }

  const NL = String.fromCharCode(10);
  await thread.send({
    content: '<@' + interaction.user.id + '> your ticket is open here.' + (staffRoleId ? ' Staff: <@&' + staffRoleId + '>' : '') + NL + NL + 'Use **/closeticket** in this thread when it is resolved.',
    allowedMentions: {
      users: [interaction.user.id],
      roles: staffRoleId ? [staffRoleId] : [],
    },
  }).catch(() => null);

  const ticketId = await createTicketRecord({
    guildId: interaction.guild.id,
    leagueId: activeLeague?.league_id || null,
    userId: interaction.user.id,
    ticketType,
    subject,
    description,
    channelId: baseChannel.id,
    threadId: thread.id,
  });

  if (gameIssueMeta) {
    await pool.query(
      `UPDATE support_tickets
       SET game_id = $1,
           request_action = $2,
           requested_team_role_id = $3,
           opponent_user_id = $4
       WHERE id = $5`,
      [gameIssueMeta.gameId || null, gameIssueMeta.requestAction || null, gameIssueMeta.requestedTeamRoleId || null, gameIssueMeta.opponentUserId || null, ticketId]
    );
  }

  if (shouldAddReviewButtons) {
    await thread.send({
      content: 'Staff review action required for this game issue request.',
      components: [buildTicketReviewButtons(ticketId)],
    }).catch(() => null);
  }

  await updateTicketPanel(interaction.guild);
  await interaction.reply({ content: 'Ticket opened: ' + thread.toString() + '. Ticket ID: **' + ticketId.split('-')[0] + '**', ephemeral: true });
}
async function ggGetOpenShopCart(guildId, userId, leagueId = null) {
  const existing = await pool.query(
    `SELECT * FROM shop_carts
     WHERE guild_id = $1 AND user_id = $2 AND status = 'open'
       AND (($3::uuid IS NULL AND league_id IS NULL) OR league_id = $3::uuid)
     ORDER BY created_at DESC
     LIMIT 1`,
    [guildId, userId, leagueId]
  );

  if (existing.rows.length) return existing.rows[0];

  const cartId = randomUUID();
  await pool.query(
    `INSERT INTO shop_carts (id, guild_id, user_id, league_id)
     VALUES ($1, $2, $3, $4)`,
    [cartId, guildId, userId, leagueId]
  );

  return { id: cartId, guild_id: guildId, user_id: userId, league_id: leagueId, status: 'open' };
}

async function ggGetShopCartItems(cartId) {
  const result = await pool.query(
    `SELECT ci.quantity, i.*
     FROM shop_cart_items ci
     JOIN shop_items i ON i.id = ci.item_id
     WHERE ci.cart_id = $1
     ORDER BY i.item_name ASC`,
    [cartId]
  );
  return result.rows;
}

async function ggAddItemToShopCart(guildId, userId, item, leagueId = null) {
  const cart = await ggGetOpenShopCart(guildId, userId, leagueId);
  await pool.query(
    `INSERT INTO shop_cart_items (cart_id, item_id, quantity)
     VALUES ($1, $2, 1)
     ON CONFLICT (cart_id, item_id)
     DO UPDATE SET quantity = shop_cart_items.quantity + 1`,
    [cart.id, item.id]
  );
  await pool.query(`UPDATE shop_carts SET updated_at = NOW() WHERE id = $1`, [cart.id]);
  return cart;
}

async function ggBuildShopCartEmbed(guildId, user, leagueId = null) {
  const settings = await getCurrencySettings(guildId);
  const cart = await ggGetOpenShopCart(guildId, user.id, leagueId);
  const items = await ggGetShopCartItems(cart.id);
  const NL = String.fromCharCode(10);
  const total = items.reduce((sum, item) => sum + Number(item.price || 0) * Number(item.quantity || 1), 0);

  const embed = new EmbedBuilder()
    .setTitle('🛒 ' + user.username + "'s Cart")
    .setColor(0xFEE75C)
    .setFooter({ text: 'GG Sports • Shop Cart' })
    .setTimestamp();

  embed.setDescription(items.length
    ? items.map(item => '• **' + item.item_name + '** x' + item.quantity + ' — ' + settings.currency_icon + ' ' + (Number(item.price) * Number(item.quantity))).join(NL)
    : 'Your cart is empty.');

  embed.addFields({ name: 'Total', value: settings.currency_icon + ' ' + total, inline: true });

  return { embed, cart, items, total, settings };
}

function ggBuildShopCartButtons(disabled = false) {
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('shop_checkout_confirm').setLabel('Checkout').setStyle(ButtonStyle.Success).setDisabled(disabled),
    new ButtonBuilder().setCustomId('shop_cart_clear').setLabel('Clear Cart').setStyle(ButtonStyle.Danger).setDisabled(disabled)
  );
}



