const EA_DIRECT_TOKEN_CLIENT_ID = process.env.EA_DIRECT_TOKEN_CLIENT_ID || EA_DIRECT_CLIENT_ID || 'MCA_26_COMP_APP';
const EA_DIRECT_TOKEN_CLIENT_SECRET = process.env.EA_DIRECT_TOKEN_CLIENT_SECRET || null;
const EA_DIRECT_TOKEN_INCLUDE_CLIENT_ID = String(process.env.EA_DIRECT_TOKEN_INCLUDE_CLIENT_ID || 'true').toLowerCase() !== 'false';
const EA_DIRECT_TOKEN_USE_BASIC_AUTH = String(process.env.EA_DIRECT_TOKEN_USE_BASIC_AUTH || 'false').toLowerCase() === 'true';
const EA_DIRECT_TOKEN_EXTRA_PARAMS = process.env.EA_DIRECT_TOKEN_EXTRA_PARAMS || null;

const EA_DIRECT_ENCRYPTION_KEY = process.env.EA_DIRECT_ENCRYPTION_KEY || null;


// EA Direct uses an unofficial auth flow. For production, set EA_DIRECT_AUTH_TEMPLATE
// in Railway to the known working EA login URL format discovered for the Madden flow.
// Supported template placeholders:
//   {STATE}
//   {REDIRECT_URI}
//   {CLIENT_ID}
// Example:
//   https://signin.ea.com/p/juno/login?...&redirect_uri={REDIRECT_URI}&state={STATE}

function getEaEncryptionKey() {
  const source = EA_DIRECT_ENCRYPTION_KEY || process.env.DATABASE_URL || 'gg-sports-dev-key';
  return crypto.createHash('sha256').update(source).digest();
}

function encryptEaSecret(value) {
  if (!value) return null;
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', getEaEncryptionKey(), iv);
  const encrypted = Buffer.concat([cipher.update(String(value), 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([iv, tag, encrypted]).toString('base64');
}

function decryptEaSecret(value) {
  if (!value) return null;
  const buffer = Buffer.from(value, 'base64');
  const iv = buffer.subarray(0, 12);
  const tag = buffer.subarray(12, 28);
  const encrypted = buffer.subarray(28);
  const decipher = crypto.createDecipheriv('aes-256-gcm', getEaEncryptionKey(), iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(encrypted), decipher.final()]).toString('utf8');
}

async function exchangeEaAuthorizationCode(code) {
  // 7J-5AB — Snallabot source-aligned EA token exchange.
  // Source alignment:
  // POST https://accounts.ea.com/connect/token
  // Headers:
  //   Accept-Charset: UTF-8
  //   User-Agent: Dalvik/2.1.0 (Linux; U; Android 13; sdk_gphone_x86_64 Build/TE1A.220922.031)
  //   Content-Type: application/x-www-form-urlencoded; charset=UTF-8
  //   Accept-Encoding: gzip
  // Body:
  //   authentication_source
  //   client_secret
  //   grant_type=authorization_code
  //   code
  //   redirect_uri
  //   release_type=prod
  //   client_id
  if (!EA_DIRECT_CLIENT_SECRET) {
    throw new Error('EA_DIRECT_CLIENT_SECRET is missing. Add it in Railway Variables before testing EA Direct token exchange.');
  }

  const body =
    'authentication_source=' + encodeURIComponent(EA_DIRECT_AUTH_SOURCE || '317239') +
    '&client_secret=' + encodeURIComponent(EA_DIRECT_CLIENT_SECRET) +
    '&grant_type=authorization_code' +
    '&code=' + encodeURIComponent(code) +
    '&redirect_uri=' + encodeURIComponent(EA_DIRECT_REDIRECT_URI || 'http://127.0.0.1/success') +
    '&release_type=prod' +
    '&client_id=' + encodeURIComponent(EA_DIRECT_CLIENT_ID || EA_DIRECT_TOKEN_CLIENT_ID || 'MCA_26_COMP_APP');

  const response = await fetch(EA_DIRECT_TOKEN_URL || 'https://accounts.ea.com/connect/token', {
    method: 'POST',
    headers: {
      'Accept-Charset': 'UTF-8',
      'User-Agent': 'Dalvik/2.1.0 (Linux; U; Android 13; sdk_gphone_x86_64 Build/TE1A.220922.031)',
      'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
      'Accept-Encoding': 'gzip',
    },
    body,
  });

  const text = await response.text();
  let payload;
  try {
    payload = JSON.parse(text);
  } catch {
    payload = { raw: text };
  }

  if (!response.ok) {
    const safeBody = body
      .replace(/code=[^&]+/g, 'code=REDACTED')
      .replace(/client_secret=[^&]+/g, 'client_secret=REDACTED');

    throw new Error(
      'EA token exchange failed: HTTP ' + response.status +
      ' • ' + (payload.error_description || payload.error || text).slice(0, 300) +
      ' • token_url=' + (EA_DIRECT_TOKEN_URL || 'https://accounts.ea.com/connect/token') +
      ' • body=' + safeBody +
      ' • auth=snallabot_body_secret'
    );
  }

  return payload;
}


async function refreshEaAccessToken(refreshToken) {
  if (!refreshToken) {
    throw new Error('EA refresh token is missing. Run /madden connect again.');
  }

  if (!EA_DIRECT_CLIENT_SECRET) {
    throw new Error('EA_DIRECT_CLIENT_SECRET is missing. Add it in Railway Variables before refreshing EA tokens.');
  }

  const body =
    'authentication_source=' + encodeURIComponent(EA_DIRECT_AUTH_SOURCE || '317239') +
    '&client_secret=' + encodeURIComponent(EA_DIRECT_CLIENT_SECRET) +
    '&grant_type=refresh_token' +
    '&refresh_token=' + encodeURIComponent(refreshToken) +
    '&release_type=prod' +
    '&client_id=' + encodeURIComponent(EA_DIRECT_CLIENT_ID || EA_DIRECT_TOKEN_CLIENT_ID || 'MCA_26_COMP_APP');

  const response = await fetch(EA_DIRECT_TOKEN_URL || 'https://accounts.ea.com/connect/token', {
    method: 'POST',
    headers: {
      'Accept-Charset': 'UTF-8',
      'User-Agent': 'Dalvik/2.1.0 (Linux; U; Android 13; sdk_gphone_x86_64 Build/TE1A.220922.031)',
      'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
      'Accept-Encoding': 'gzip',
    },
    body,
  });

  const text = await response.text();
  let payload;
  try {
    payload = JSON.parse(text);
  } catch {
    payload = { raw: text };
  }

  if (!response.ok || payload?.error) {
    const safeBody = body
      .replace(/refresh_token=[^&]+/g, 'refresh_token=REDACTED')
      .replace(/client_secret=[^&]+/g, 'client_secret=REDACTED');

    throw new Error(
      'EA token refresh failed: HTTP ' + response.status +
      ' • ' + (payload.error_description || payload.error || text).slice(0, 300) +
      ' • token_url=' + (EA_DIRECT_TOKEN_URL || 'https://accounts.ea.com/connect/token') +
      ' • body=' + safeBody
    );
  }

  return payload;
}

function isEaExpiredTokenError(error) {
  const message = String(error?.message || error || '');
  return message.includes('AUTH_ERR_EXPIRED_TOKEN') ||
    message.toLowerCase().includes('expired_token') ||
    message.toLowerCase().includes('expired token');
}

function isEaInvalidRequestTokenError(error) {
  const message = String(error?.message || error || '');
  return message.includes('AUTH_ERR_INVALID_REQUEST') ||
    message.includes('"errorcode":131073') ||
    message.toLowerCase().includes('invalid_request');
}

function summarizeEaTokenForLog(token) {
  return {
    hasAccessToken: Boolean(token?.accessToken),
    accessTokenLength: token?.accessToken ? String(token.accessToken).length : 0,
    hasRefreshToken: Boolean(token?.refreshToken),
    refreshTokenLength: token?.refreshToken ? String(token.refreshToken).length : 0,
    expiry: token?.expiry ? String(token.expiry) : null,
    console: token?.console || null,
    blazeId: token?.blazeId || null,
  };
}



async function refreshEaConnectionTokens(connection, existingRefreshToken) {
  const refreshToken = existingRefreshToken || decryptEaSecret(connection.refresh_token_encrypted);
  const payload = await refreshEaAccessToken(refreshToken);

  const nextAccessToken = payload.access_token;
  const nextRefreshToken = payload.refresh_token || refreshToken;

  if (!nextAccessToken) {
    throw new Error('EA token refresh response did not include an access token.');
  }

  await pool.query(
    `UPDATE madden_ea_connections
     SET access_token_encrypted = $2,
         refresh_token_encrypted = COALESCE($3, refresh_token_encrypted),
         token_expires_at = $4,
         token_type = $5,
         token_scope = $6,
         raw_token_payload = $7::jsonb,
         last_error = NULL,
         updated_at = NOW()
     WHERE id = $1`,
    [
      connection.id,
      encryptEaSecret(nextAccessToken),
      nextRefreshToken ? encryptEaSecret(nextRefreshToken) : null,
      payload.expires_in ? new Date(Date.now() + Number(payload.expires_in) * 1000) : null,
      payload.token_type || connection.token_type || null,
      payload.scope || connection.token_scope || null,
      JSON.stringify(payload || {}),
    ]
  );

  console.log('[EA Direct] Refreshed EA token for connection:', {
    connectionId: connection.id,
    expiresIn: payload.expires_in || null,
    tokenType: payload.token_type || null,
  });

  return {
    accessToken: nextAccessToken,
    refreshToken: nextRefreshToken,
    expiry: payload.expires_in ? new Date(Date.now() + Number(payload.expires_in) * 1000) : new Date(Date.now() + 60 * 60 * 1000),
    payload,
  };
}


async function fetchEaJson(url, accessToken, label) {
  if (!url) {
    throw new Error(label + ' endpoint is not configured.');
  }

  const response = await fetch(url, {
    method: 'GET',
    headers: {
      'Accept': 'application/json',
      'Authorization': 'Bearer ' + accessToken,
    },
  });

  const text = await response.text();
  let payload;
  try {
    payload = JSON.parse(text);
  } catch {
    payload = { raw: text };
  }

  if (!response.ok) {
    throw new Error(label + ' request failed: HTTP ' + response.status + ' • ' + (payload.error_description || payload.error || text).slice(0, 300));
  }

  return payload;
}

