async function completeEaRetrievePersonasViaEndpoint(guildId, leagueId, userId, code) {
  if (!EA_DIRECT_RETRIEVE_PERSONAS_URL) {
    throw new Error('EA_DIRECT_RETRIEVE_PERSONAS_URL is not configured.');
  }

  let payload;
  try {
    payload = await postJsonToEndpoint(EA_DIRECT_RETRIEVE_PERSONAS_URL, {
      code,
      guild_id: guildId,
      league_id: leagueId,
      user_id: userId,
    }, 'EA retrieve-personas');
  } catch (error) {
    console.error('[EA Direct] retrieve-personas endpoint failed, using internal handler fallback:', error?.message || error);
    const fallback = await handleInternalRetrievePersonas({
      code,
      guild_id: guildId,
      league_id: leagueId,
      user_id: userId,
    });
    if (fallback.statusCode >= 400) {
      throw new Error(fallback.payload?.error || 'EA retrieve-personas fallback failed.');
    }
    payload = fallback.payload;
  }

  const personas = await saveEaPersonas(guildId, leagueId, userId, payload);

  const tokenPayload = payload?.tokenPayload || payload?.token || null;
  const accessToken = payload?.access_token || payload?.accessToken || tokenPayload?.access_token || null;
  const refreshToken = payload?.refresh_token || payload?.refreshToken || tokenPayload?.refresh_token || null;

  await pool.query(
    `UPDATE madden_ea_connections
     SET access_token_encrypted = COALESCE($4, access_token_encrypted),
         refresh_token_encrypted = COALESCE($5, refresh_token_encrypted),
         raw_personas_payload = $6::jsonb,
         exchange_status = 'personas_fetched',
         connection_status = 'personas_fetched',
         last_error = NULL,
         updated_at = NOW()
     WHERE league_id = $1 AND user_id = $2 AND provider = $3`,
    [
      leagueId,
      userId,
      'ea_direct',
      accessToken ? encryptEaSecret(accessToken) : null,
      refreshToken ? encryptEaSecret(refreshToken) : null,
      JSON.stringify(payload || {}),
    ]
  ).catch(() => null);

  const connection = await getMaddenEaConnection(leagueId, userId);
  return {
    payload,
    personas,
    personaCount: personas.length,
    connection,
  };
}


async function completeEaTokenExchange(guildId, leagueId, userId, code) {
  const tokenPayload = await exchangeEaAuthorizationCode(code);
  const accessToken = tokenPayload.access_token;
  const refreshToken = tokenPayload.refresh_token;
  const expiresIn = Number(tokenPayload.expires_in || 0);
  const expiresAt = expiresIn ? new Date(Date.now() + expiresIn * 1000) : null;

  if (!accessToken) {
    throw new Error('EA token exchange response did not include an access_token.');
  }

  await pool.query(
    `UPDATE madden_ea_connections
     SET access_token_encrypted = $4,
         refresh_token_encrypted = $5,
         token_expires_at = $6,
         token_type = $7,
         token_scope = $8,
         raw_token_payload = $9,
         exchange_status = 'token_exchanged',
         connection_status = 'token_exchanged',
         last_error = NULL,
         updated_at = NOW()
     WHERE league_id = $1 AND user_id = $2 AND provider = $3`,
    [
      leagueId,
      userId,
      'ea_direct',
      encryptEaSecret(accessToken),
      encryptEaSecret(refreshToken),
      expiresAt,
      tokenPayload.token_type || null,
      tokenPayload.scope || null,
      JSON.stringify(tokenPayload),
    ]
  );

  let personaCount = 0;
  let personaPayload = null;

  if (EA_DIRECT_PERSONAS_URL) {
    personaPayload = await fetchEaJson(EA_DIRECT_PERSONAS_URL, accessToken, 'EA personas');
    personaCount = await saveEaPersonas(guildId, leagueId, userId, personaPayload);
    await pool.query(
      `UPDATE madden_ea_connections SET raw_personas_payload = $3, exchange_status = 'personas_fetched', updated_at = NOW()
       WHERE league_id = $1 AND user_id = $2 AND provider = 'ea_direct'`,
      [leagueId, userId, JSON.stringify(personaPayload)]
    );
  }

  const connection = await getMaddenEaConnection(leagueId, userId);
  return { connection, tokenPayload, personaCount };
}

