async function postMaddenSyncFeed(guild, league, run) {
  const settingsResult = await pool.query(
    `SELECT * FROM madden_league_settings WHERE league_id = $1 LIMIT 1`,
    [league.league_id]
  );
  const settings = settingsResult.rows[0] || {};
  const channelId = settings.sync_feed_channel_id || league.sportsbook_channel_id || null;
  if (!channelId) return null;

  const channel = await guild.channels.fetch(channelId).catch(() => null);
  if (!channel || !channel.isTextBased()) return null;

  const embed = buildMaddenSyncRunEmbed(league, run)
    .setTitle((run.status === 'failed' ? '⚠️ Madden Sync Failed • ' : '✅ Madden Sync Complete • ') + league.league_name)
    .setFooter({ text: 'GG Sports • Madden Auto Sync' })
    .setTimestamp();

  return channel.send({ embeds: [embed] }).catch(() => null);
}

async function setMaddenAutosync(league, enabled, minutes = null) {
  const interval = Math.max(Number(minutes || 60), 15);
  const nextSync = enabled ? new Date(Date.now() + interval * 60 * 1000) : null;
  await ensureMaddenLeagueSettings(league);
  await pool.query(
    `UPDATE madden_league_settings
     SET autosync_enabled = $2, autosync_interval_minutes = $3, next_sync_at = $4, updated_at = NOW()
     WHERE league_id = $1`,
    [league.league_id, enabled, interval, nextSync]
  );
  const result = await pool.query(`SELECT * FROM madden_league_settings WHERE league_id = $1 LIMIT 1`, [league.league_id]);
  return result.rows[0] || {};
}

async function setMaddenSyncFeedChannel(league, channelId) {
  await ensureMaddenLeagueSettings(league);
  await pool.query(
    `UPDATE madden_league_settings SET sync_feed_channel_id = $2, updated_at = NOW() WHERE league_id = $1`,
    [league.league_id, channelId]
  );
  const result = await pool.query(`SELECT * FROM madden_league_settings WHERE league_id = $1 LIMIT 1`, [league.league_id]);
  return result.rows[0] || {};
}

function buildMaddenAutosyncEmbed(league, settings) {
  return new EmbedBuilder()
    .setTitle('Madden Auto Sync • ' + league.league_name)
    .setColor(settings.autosync_enabled ? 0x57F287 : 0xED4245)
    .addFields(
      { name: 'Enabled', value: settings.autosync_enabled ? 'Yes' : 'No', inline: true },
      { name: 'Interval', value: String(settings.autosync_interval_minutes || 60) + ' minutes', inline: true },
      { name: 'Next Sync', value: settings.next_sync_at ? String(settings.next_sync_at) : 'Not scheduled', inline: true },
      { name: 'Feed Channel', value: settings.sync_feed_channel_id ? '<#' + settings.sync_feed_channel_id + '>' : 'Not set', inline: true },
      { name: 'Source', value: settings.sync_source || 'Not linked', inline: true },
      { name: 'External URL', value: settings.external_url || 'Not set', inline: false }
    )
    .setFooter({ text: 'GG Sports • Madden Autosync' })
    .setTimestamp();
}

let maddenAutosyncTimer = null;
let maddenAutosyncRunning = false;

async function runDueMaddenAutosyncs(client) {
  if (maddenAutosyncRunning) return;
  maddenAutosyncRunning = true;
  try {
    const due = await pool.query(
      `SELECT mls.*, l.guild_id AS league_guild_id, l.league_name
       FROM madden_league_settings mls
       JOIN leagues l ON l.league_id = mls.league_id
       WHERE mls.autosync_enabled = TRUE
         AND (mls.next_sync_at IS NULL OR mls.next_sync_at <= NOW())
       ORDER BY mls.next_sync_at ASC NULLS FIRST
       LIMIT 10`
    );

    for (const row of due.rows) {
      const guildId = row.guild_id || row.league_guild_id;
      const guild = await client.guilds.fetch(guildId).catch(() => null);
      if (!guild) continue;
      const league = await getLeagueById(row.league_id);
      if (!league) continue;

      let run;
      try {
        run = await runMaddenExternalFetchSync(guild, league, { week: null });
      } catch (error) {
        run = { status: 'failed', source: row.sync_source || 'unknown', message: error.message || 'Autosync failed.', imported_teams: 0, imported_games: 0, imported_players: 0 };
      }
      await postMaddenSyncFeed(guild, league, run).catch(() => null);

      const interval = Math.max(Number(row.autosync_interval_minutes || 60), 15);
      await pool.query(
        `UPDATE madden_league_settings
         SET next_sync_at = NOW() + ($2::int * INTERVAL '1 minute'), updated_at = NOW()
         WHERE league_id = $1`,
        [row.league_id, interval]
      );
    }
  } catch (error) {
    console.error('Madden autosync loop failed:', error);
  } finally {
    maddenAutosyncRunning = false;
  }
}

function startMaddenAutosyncLoop(client) {
  if (maddenAutosyncTimer) clearInterval(maddenAutosyncTimer);
  maddenAutosyncTimer = setInterval(() => {
    runDueMaddenAutosyncs(client).catch(error => console.error('Madden autosync tick failed:', error));
  }, 60 * 1000);
  setTimeout(() => runDueMaddenAutosyncs(client).catch(() => null), 10 * 1000);
}


async function runMaddenExternalFetchSync(guild, league, options = {}) {
  const settings = await ensureMaddenLeagueSettings(league);
  const eaConnectionResult = await pool.query(
    `SELECT id FROM madden_ea_connections
     WHERE league_id = $1 AND provider = 'ea_direct' AND connection_status = 'connected'
     LIMIT 1`,
    [league.league_id]
  );

  if (settings.sync_source === 'ea_direct' || eaConnectionResult.rows.length) {
    return await runMaddenEaDirectSync(guild, league, options);
  }

  const runId = randomUUID();
  const source = normalizeMaddenSource(settings.sync_source || 'unlinked');

  await pool.query(
    `INSERT INTO madden_sync_runs (id, guild_id, league_id, source, status, week_label, message)
     VALUES ($1, $2, $3, $4, 'running', $5, $6)`,
    [runId, guild.id, league.league_id, source, options.week || null, 'External Madden sync started.']
  );

  if (!settings.external_url) {
    const message = 'No external URL linked. Use /madden link with a source URL first.';
    await pool.query(
      `UPDATE madden_sync_runs SET status = 'failed', message = $2, completed_at = NOW() WHERE id = $1`,
      [runId, message]
    );
    await pool.query(
      `UPDATE madden_league_settings SET last_sync_at = NOW(), last_sync_status = 'failed', last_sync_message = $2, updated_at = NOW() WHERE league_id = $1`,
      [league.league_id, message]
    );
    const failed = await pool.query(`SELECT * FROM madden_sync_runs WHERE id = $1 LIMIT 1`, [runId]);
    return failed.rows[0];
  }

  const endpoints = buildMaddenEndpointList(settings);
  const totals = { teams: 0, games: 0, players: 0 };
  const errors = [];
  let successfulEndpoints = 0;

  for (const endpoint of endpoints) {
    try {
      const payload = await fetchJsonWithTimeout(endpoint.url, { apiKey: settings.api_key });
      await pool.query(
        `INSERT INTO madden_sync_payloads (id, guild_id, league_id, sync_run_id, endpoint, payload_type, raw_payload)
         VALUES ($1, $2, $3, $4, $5, $6, $7)`,
        [randomUUID(), guild.id, league.league_id, runId, endpoint.url, endpoint.type, JSON.stringify(payload)]
      );

      const rows = extractMaddenRowsByType(payload, endpoint.type);
      if (!rows.length) {
        errors.push(endpoint.type + ': no rows found at ' + endpoint.url);
        continue;
      }

      const counts = await importMaddenRowsByType(guild, league, endpoint.type, rows, options.week || null);
      totals.teams += Number(counts.teams || 0);
      totals.games += Number(counts.games || 0);
      totals.players += Number(counts.players || 0);
      successfulEndpoints += 1;
    } catch (error) {
      errors.push(endpoint.type + ': ' + (error.message || 'fetch failed'));
    }
  }

  // Always keep local Discord team bridge updated too.
  await syncMaddenFranchises(guild, league).catch(error => errors.push('local team bridge: ' + error.message));

  const status = successfulEndpoints > 0 ? 'completed' : 'failed';
  const message = successfulEndpoints > 0
    ? 'External sync completed. Imported teams: ' + totals.teams + ', games: ' + totals.games + ', players: ' + totals.players + (errors.length ? '. Some endpoints had warnings.' : '.')
    : 'External sync failed. ' + errors.slice(0, 3).join(' | ');

  await pool.query(
    `UPDATE madden_sync_runs
     SET status = $2,
         message = $3,
         imported_teams = $4,
         imported_games = $5,
         imported_players = $6,
         completed_at = NOW()
     WHERE id = $1`,
    [runId, status, message, totals.teams, totals.games, totals.players]
  );

  await pool.query(
    `UPDATE madden_league_settings
     SET last_sync_at = NOW(),
         last_sync_status = $2,
         last_sync_message = $3,
         updated_at = NOW()
     WHERE league_id = $1`,
    [league.league_id, status, message]
  );

  const runResult = await pool.query(`SELECT * FROM madden_sync_runs WHERE id = $1 LIMIT 1`, [runId]);
  return runResult.rows[0];
}


async function runMaddenExternalSyncPlaceholder(guild, league, options = {}) {
  const settings = await ensureMaddenLeagueSettings(league);
  const runId = randomUUID();

  await pool.query(
    `INSERT INTO madden_sync_runs (id, guild_id, league_id, source, status, week_label, message)
     VALUES ($1, $2, $3, $4, 'running', $5, $6)`,
    [runId, guild.id, league.league_id, settings.sync_source || 'unlinked', options.week || null, 'Madden sync started.']
  );

  // V1 foundation: no external provider API is hardcoded yet.
  // This creates the import pipeline, sync log, and local franchise/team bridge.
  // Once the exact Neon/league export source is confirmed, this function becomes the real fetch/import worker.
  await syncMaddenFranchises(guild, league).catch(() => null);

  const teams = await pool.query(
    `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id = $2 ORDER BY team_name ASC`,
    [guild.id, league.league_id]
  );

  for (const team of teams.rows) {
    await pool.query(
      `INSERT INTO madden_imported_team_stats (guild_id, league_id, team_name, team_role_id, owner_user_id, wins, losses, ties)
       VALUES ($1, $2, $3, $4, $5, 0, 0, 0)
       ON CONFLICT (league_id, team_name)
       DO UPDATE SET team_role_id = $4, owner_user_id = $5, imported_at = NOW()`,
      [guild.id, league.league_id, team.team_name, team.team_role_id, team.owner_user_id || null]
    );
  }

  const message = settings.sync_source
    ? 'Sync foundation completed. Teams were bridged locally. External fetch/import worker is ready for provider wiring.'
    : 'No external Madden source linked yet. Use /madden link first. Local teams were still bridged.';

  await pool.query(
    `UPDATE madden_sync_runs
     SET status = 'completed',
         message = $2,
         imported_teams = $3,
         completed_at = NOW()
     WHERE id = $1`,
    [runId, message, teams.rows.length]
  );

  await pool.query(
    `UPDATE madden_league_settings
     SET last_sync_at = NOW(),
         last_sync_status = 'completed',
         last_sync_message = $2,
         updated_at = NOW()
     WHERE league_id = $1`,
    [league.league_id, message]
  );

  const runResult = await pool.query(`SELECT * FROM madden_sync_runs WHERE id = $1 LIMIT 1`, [runId]);
  return runResult.rows[0] || { id: runId, status: 'completed', message };
}

async function getMaddenImportedStatus(guildId, leagueId) {
  const [teams, games, players, runs] = await Promise.all([
    pool.query(`SELECT COUNT(*)::int AS count FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id = $2`, [guildId, leagueId]),
    pool.query(`SELECT COUNT(*)::int AS count FROM madden_imported_games WHERE guild_id = $1 AND league_id = $2`, [guildId, leagueId]),
    pool.query(`SELECT COUNT(*)::int AS count FROM madden_imported_players WHERE guild_id = $1 AND league_id = $2`, [guildId, leagueId]),
    pool.query(`SELECT * FROM madden_sync_runs WHERE guild_id = $1 AND league_id = $2 ORDER BY started_at DESC LIMIT 5`, [guildId, leagueId]),
  ]);

  return {
    teams: Number(teams.rows[0]?.count || 0),
    games: Number(games.rows[0]?.count || 0),
    players: Number(players.rows[0]?.count || 0),
    runs: runs.rows,
  };
}

